#!/usr/bin/env python3
"""Deterministically bundle the development sources into Burp's single-file artifact."""
import argparse
import ast
from pathlib import Path
import sys

ROOT = Path(__file__).resolve().parents[1]
MODULES = (
    'recon.core.evidence',
    'recon.core.iranian',
    'recon.core.extraction',
    'recon.burp.extension',
)
ARTIFACT = ROOT / 'ReconSwissKnife_v3.py'


def build(root=ROOT, modules=MODULES):
    parts = ['# -*- coding: utf-8 -*-\n',
             '# GENERATED by tools/bundle.py. Edit recon/ sources, then rebuild.\n',
             '# This artifact runs independently; no recon/ package is needed in Burp.\n']
    included = set()
    for name in modules:
        path = root.joinpath(*name.split('.')).with_suffix('.py')
        source = path.read_text(encoding='utf-8')
        tree = ast.parse(source, filename=str(path))
        lines = source.splitlines(keepends=True)
        for node in ast.walk(tree):
            if isinstance(node, ast.Import):
                if any(a.name == 'recon' or a.name.startswith('recon.') for a in node.names):
                    raise ValueError('Use explicit from-imports for bundled dependencies: ' + name)
            if isinstance(node, ast.ImportFrom):
                if node.level or node.module == '__future__':
                    raise ValueError('Relative/future imports are unsupported in bundled modules: ' + name)
                if node.module and node.module.startswith('recon.'):
                    if node not in tree.body or node.module not in included:
                        raise ValueError('Dependency must be a preceding module, imported at top level: ' + node.module)
                    if any(a.asname or a.name == '*' for a in node.names):
                        raise ValueError('Aliases and star imports are unsupported in bundled modules: ' + name)
                    for i in range(node.lineno-1, node.end_lineno):
                        lines[i] = ''
        source = ''.join(lines)
        if source.startswith('# -*- coding: utf-8 -*-\n'):
            source = source.split('\n',1)[1]
        parts.append('\n# === ' + name + ' ===\n' + source.rstrip() + '\n')
        included.add(name)
    result = ''.join(parts)
    compile(result, str(ARTIFACT), 'exec')
    return result


def main():
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument('--check', action='store_true', help='fail if the committed artifact differs from sources')
    parser.add_argument('--output', type=Path, default=ARTIFACT)
    args = parser.parse_args()
    expected = build()
    if args.check:
        if not args.output.exists() or args.output.read_bytes() != expected.encode('utf-8'):
            print('Bundle is stale. Run python3 tools/bundle.py', file=sys.stderr)
            return 1
        print('Bundle matches development sources.')
    else:
        args.output.write_bytes(expected.encode('utf-8'))
        print('Wrote ' + str(args.output))
    return 0


if __name__ == '__main__':
    sys.exit(main())
